// Antes de la herencia: un solo lugar que conoce a todos los tipos de vehículo
function costoEnvio(vehiculo, km, kg) {
  if (vehiculo.tipo === "camion") return 5 + km * 0.8 + kg * 0.05;
  if (vehiculo.tipo === "moto") return 3 + km * 0.35;
  throw new Error(`No sé cotizar un «${vehiculo.tipo}»`);
}

