class Vehiculo {
  constructor(patente) {
    // JavaScript no tiene la palabra «abstract»: se simula con new.target,
    // que vale la clase sobre la que alguien escribió «new»
    if (new.target === Vehiculo) {
      throw new TypeError("Vehiculo es abstracta: creá un Camion, una Moto, etc.");
    }
    this.patente = patente;
  }

  // El «hueco» que cada subclase debe llenar
  costoEnvio(km, kg) {
    throw new Error(`${this.constructor.name} tiene que implementar costoEnvio()`);
  }

  // Un método concreto que usa el hueco: sirve igual para todas las subclases
  presupuesto(km, kg) {
    return `${this.patente}: $${this.costoEnvio(km, kg).toFixed(2)} por ${km} km`;
  }
}

