// La clase base: dos métodos, y uno de ellos usa al otro por dentro
class Manifiesto {
  constructor() {
    this.envios = [];
  }
  agregar(envio) {
    this.envios.push(envio);
  }
  agregarTodos(lista) {
    for (const e of lista) this.agregar(e); // detalle interno: llama a agregar
  }
}

// Versión 1, por herencia: quiero contar cuántos envíos se agregaron
class ContadoPorHerencia extends Manifiesto {
  constructor() {
    super();
    this.agregados = 0;
  }
  agregar(envio) {
    this.agregados++;
    super.agregar(envio);
  }
  agregarTodos(lista) {
    this.agregados += lista.length;
    super.agregarTodos(lista); // ...que por dentro llama a this.agregar y vuelve a contar
  }
}

const h = new ContadoPorHerencia();
h.agregarTodos(["Rosario", "Mendoza", "Salta"]);
console.log("herencia:", h.agregados, "contados,", h.envios.length, "envíos reales");

// Versión 2, por composición: el contador TIENE un manifiesto, no ES uno
class ContadoPorComposicion {
  #manifiesto = new Manifiesto();
  agregados = 0;
  agregar(envio) {
    this.agregados++;
    this.#manifiesto.agregar(envio);
  }
  agregarTodos(lista) {
    for (const e of lista) this.agregar(e); // usa solo la interfaz pública de sí mismo
  }
  get envios() {
    return [...this.#manifiesto.envios];
  }
}

const c = new ContadoPorComposicion();
c.agregarTodos(["Rosario", "Mendoza", "Salta"]);
console.log("composición:", c.agregados, "contados,", c.envios.length, "envíos reales");

// Piezas sueltas, sin padre común: cada una sabe cuánto suma por km
class Refrigeracion {
  nombre = "refrigeración";
  costoPorKm() {
    return 0.3;
  }
}

class Gps {
  nombre = "GPS";
  costoPorKm() {
    return 0.02;
  }
}

// El camión TIENE equipos; no hay un CamionFrigorificoConGps heredando de otro
class Camion {
  constructor(patente, equipos = []) {
    this.patente = patente;
    this.equipos = equipos;
  }
  costoEnvio(km) {
    const base = 5 + km * 0.8;
    const extras = this.equipos.reduce((suma, eq) => suma + eq.costoPorKm() * km, 0);
    return base + extras;
  }
  describir() {
    const lista = this.equipos.map((eq) => eq.nombre).join(" + ") || "sin equipos";
    return `${this.patente} (${lista})`;
  }
}

const flota = [
  new Camion("AB123CD"),
  new Camion("CD456EF", [new Refrigeracion()]),
  new Camion("EF789GH", [new Refrigeracion(), new Gps()]),
];
for (const c of flota) console.log(c.describir().padEnd(36), "$" + c.costoEnvio(100).toFixed(2));

// Duck typing: un objeto suelto, sin clase, sirve si responde a costoPorKm()
const balanza = { nombre: "balanza", costoPorKm: () => 0.01 };
console.log(new Camion("GH012IJ", [balanza]).describir());

// ...y uno que no responde falla recién cuando se lo usa
