// Una cadena de seis niveles: cada clase retoca el resultado de la de arriba
class Vehiculo {
  costo(km) { return 10; }
}
class VehiculoTerrestre extends Vehiculo {
  costo(km) { return super.costo(km) + km * 0.5; }
}
class VehiculoDeCarga extends VehiculoTerrestre {
  costo(km) { return super.costo(km) * 1.1; }
}
class Camion extends VehiculoDeCarga {
  costo(km) { return super.costo(km) + 20; }
}
class CamionFrigorifico extends Camion {
  costo(km) { return super.costo(km) * 1.25; }
}
class CamionFrigorificoConAcoplado extends CamionFrigorifico {
  costo(km) { return super.costo(km) + 15; }
}

const v = new CamionFrigorificoConAcoplado();
console.log(v.costo(100));

// El camino que recorre el motor para encontrar costo, de abajo hacia arriba
let clase = Object.getPrototypeOf(v);
const camino = [];
while (clase !== Object.prototype) {
  camino.push(clase.constructor.name);
  clase = Object.getPrototypeOf(clase);
}
console.log(camino.join(" -> "));

interface Cotizable {
  costoEnvio(km: number, kg: number): number;
}

function mejorPrecio(opciones: Cotizable[], km: number, kg: number): number {
  return Math.min(...opciones.map((o) => o.costoEnvio(km, kg)));
}

// Sin clase y sin extends: alcanza con tener la forma
const bici = { costoEnvio: (km: number) => 2 + km * 0.2 };
console.log(mejorPrecio([bici], 10, 2));

const taxi = { tarifa: 3 };
mejorPrecio([taxi], 10, 2);
